/* HA Motorsport Card - dev preview */
const COLORS={F1:'#078b52',F2:'#a71048',F3:'#bc501d','F1 Academy':'#073b70',MotoGP:'#a30b43',Moto2:'#4e609e',Moto3:'#7044a6',WRC:'#d80025',WEC:'#224b90'};
const FLAGS={Brazil:'🇧🇷',Qatar:'🇶🇦',Monaco:'🇲🇨',Portugal:'🇵🇹',Spain:'🇪🇸','United States':'🇺🇸','United Arab Emirates':'🇦🇪'};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;','\'':'&#39;'}[c]));
const fmt=t=>new Intl.DateTimeFormat(undefined,{weekday:'short',day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}).format(new Date(t));
const clock=t=>{let s=Math.max(0,Math.floor(t/1000));return [Math.floor(s/86400),Math.floor(s/3600)%24,Math.floor(s/60)%60,s%60].map(n=>String(n).padStart(2,'0'))};
function normalize(e){const info={};for(const line of String(e.description||'').split(/\r?\n/)){const match=line.match(/^\s*([^:]+):\s*(.*?)\s*,?\s*$/);if(match)info[match[1].toLowerCase().trim()]=match[2].replace(/,$/,'').trim()}const short=String(e.summary||'').split(':')[0].trim();const series=short||info.series||'Unknown';const start=Date.parse(e.start),end=Date.parse(e.end);return {series,full:info.series||series,event:info.event||e.summary||'Event',session:info.session||'Session',location:info.location||e.location||'',country:String(info.location||e.location||'').split(',').pop().trim(),start,end,allDay:!!e.all_day}}
const css=`:host{display:block;color:#fff}*{box-sizing:border-box}.shell{font-family:var(--paper-font-body1_-_font-family,Arial,sans-serif);background:linear-gradient(115deg,var(--accent),#0d1a2d 72%);border-radius:16px;padding:18px;color:#fff;overflow:hidden;touch-action:pan-y;user-select:none}.top,.bottom,.line{display:flex;align-items:center;justify-content:space-between;gap:10px}.badge{font-size:12px;font-weight:700;background:#071321c9;border-radius:5px;padding:5px 8px}.title{font-size:clamp(22px,3.8vw,30px);font-weight:750;line-height:1.15;overflow-wrap:anywhere;margin:14px 0 6px}.place{opacity:.86;font-size:14px}.count{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:5px;margin:17px 0}.cell{background:#050c15ac;border-radius:6px;text-align:center;padding:10px 2px}.num{font-size:clamp(19px,4vw,29px);font-weight:750;font-variant-numeric:tabular-nums}.unit{opacity:.75;font-size:11px}.bottom{background:#060b14aa;padding:10px;border-radius:6px;font-size:13px}.schedule{padding:12px;background:#071321a6;border-radius:8px;margin-top:12px}.line{border-bottom:1px solid #ffffff24;padding:8px 0;font-size:13px}.line:last-child{border:0}.status{opacity:.8;font-size:11px}.btn{background:#ffffff1c;color:#fff;border:1px solid #ffffff55;border-radius:7px;padding:8px 12px;cursor:pointer;margin-top:12px}.error{font-size:12px;margin-top:8px;color:#ffe0b2}.compact .title{font-size:21px}.compact .count{margin:10px 0}.compact .cell{padding:6px 2px}@media(max-width:400px){.shell{padding:13px}.unit{font-size:10px}.num{font-size:20px}.place{font-size:12px}}`;
class MotorsportCard extends HTMLElement{
constructor(){super();this.attachShadow({mode:'open'});this._config={};this._events=[];this._expanded=false;this._lastFetch=0;this._loading=false;this._timer=null;this._holdTimer=null;this._held=false;this._startPos=null}
setConfig(config){if(!config||typeof config!=='object')throw Error('Missing config');this._config={calendar_entity:'calendar.lightsouts',series:'all',days_ahead:60,refresh_minutes:30,compact:false,hold_action:{action:'none'},...config};this._lastFetch=0;this.render();this.fetchEvents()}
set hass(h){this._hass=h;if(!this._timer)this._timer=setInterval(()=>{if(Date.now()-this._lastFetch>=Math.max(5,Number(this._config.refresh_minutes)||30)*60000)this.fetchEvents();this.render()},1000);if(!this._lastFetch)this.fetchEvents()}
connectedCallback(){this.render()}
disconnectedCallback(){clearInterval(this._timer);this._timer=null;clearTimeout(this._holdTimer)}
getCardSize(){return this._expanded?6:3}
static getStubConfig(){return {type:'custom:motorsport-card',calendar_entity:'calendar.lightsouts',series:'all'}}
async fetchEvents(){if(!this._hass||this._loading)return;this._loading=true;try{const entity=this._config.calendar_entity;const data=await this._hass.callWS({type:'call_service',domain:'calendar',service:'get_events',service_data:{duration:{days:Math.max(1,Math.min(365,Number(this._config.days_ahead)||60))}},target:{entity_id:entity},return_response:true});const events=data?.response?.[entity]?.events||data?.[entity]?.events||[];if(!Array.isArray(events))throw Error('Unexpected calendar response');this._events=events.map(normalize).filter(e=>Number.isFinite(e.start)&&Number.isFinite(e.end)).sort((a,b)=>a.start-b.start);this._error=''}catch(e){this._error=String(e.message||e)}finally{this._loading=false;this._lastFetch=Date.now();this.render()}}
onHold(){const a=this._config.hold_action||{};if(a.action==='navigate'&&typeof a.navigation_path==='string'&&a.navigation_path.startsWith('/')){history.pushState(null,'',a.navigation_path);window.dispatchEvent(new Event('location-changed'))}else if(a.action==='more-info'){this.dispatchEvent(new CustomEvent('hass-more-info',{detail:{entityId:this._config.calendar_entity},bubbles:true,composed:true}))}}
render(){if(!this.shadowRoot)return;const now=Date.now(),chosen=String(this._config.series||'all').toLowerCase();const filtered=this._events.filter(e=>(chosen==='all'||chosen===e.series.toLowerCase()||chosen===e.full.toLowerCase())&&e.end>now);const current=filtered.find(e=>e.start<=now&&now<e.end),next=current||filtered[0],accent=COLORS[next?.series]||'#174a80',values=next?clock(next.start-now):['--','--','--','--'];const schedule=next?filtered.filter(e=>e.series===next.series&&e.event===next.event):[];this.shadowRoot.innerHTML=`<style>${css}</style><div class="shell ${this._config.compact?'compact':''}" style="--accent:${accent}"><div class="top"><span class="badge">🏁 ${esc(next?.series||this._config.series||'Motorsport')}</span><span class="status">${current?'🔴 Schemalagd tid pågår':next?'Nästa session':'Kalender'}</span></div><div class="title">${esc(next?.event||'Ingen kommande session')}</div><div class="place">${FLAGS[next?.country]||'🏁'} ${esc(next?.location||'')}</div><div class="count">${values.map((n,i)=>`<div class="cell"><div class="num">${n}</div><div class="unit">${['Dagar','Timmar','Minuter','Sekunder'][i]}</div></div>`).join('')}</div><div class="bottom"><span>${esc(next?.session||'Inga händelser')}</span><span>${next?(next.allDay?'Heldag':fmt(next.start)):'—'}</span></div>${this._expanded?`<div class="schedule"><strong>Helgschema</strong>${schedule.map(e=>`<div class="line"><span>${esc(e.session)}</span><span>${e.allDay?'Heldag':fmt(e.start)}</span></div>`).join('')||'<p>Inga sessioner</p>'}</div>`:''}${this._error?`<div class="error">Kalender: ${esc(this._error)}</div>`:''}<button class="btn" type="button" aria-expanded="${this._expanded}">${this._expanded?'Dölj helgschema':'Visa helgschema'}</button></div>`;const root=this.shadowRoot.querySelector('.shell');root.addEventListener('pointerdown',e=>{if(e.target.closest('button'))return;this._held=false;this._startPos=[e.clientX,e.clientY];clearTimeout(this._holdTimer);this._holdTimer=setTimeout(()=>{this._held=true;this.onHold()},650)});root.addEventListener('pointermove',e=>{if(this._startPos&&Math.hypot(e.clientX-this._startPos[0],e.clientY-this._startPos[1])>12)clearTimeout(this._holdTimer)});for(const kind of ['pointerup','pointercancel','pointerleave'])root.addEventListener(kind,()=>clearTimeout(this._holdTimer));root.addEventListener('contextmenu',e=>e.preventDefault());root.addEventListener('click',e=>{if(e.target.closest('button')||this._held)return;this._expanded=!this._expanded;this.render()});root.querySelector('button').addEventListener('click',e=>{e.stopPropagation();this._expanded=!this._expanded;this.render()})}
}
if(!customElements.get('motorsport-card'))customElements.define('motorsport-card',MotorsportCard);
window.customCards=window.customCards||[];if(!window.customCards.some(c=>c.type==='motorsport-card'))window.customCards.push({type:'motorsport-card',name:'Motorsport Card (dev)',description:'Lightsouts calendar countdown and schedule'});
